from fractions import Fraction

def calculate_Px(x, A):
    i_plus_1 = len(A)
    Px = 1
    ax = A[x-1]
    for y in range(1, i_plus_1 + 1):
        if y != x:
            ay = A[y-1]
            numerator = ax * ay - 1
            denominator = ax - ay
            if denominator == 0:
                return None
            Px *= Fraction(numerator, denominator)
    return Px

def calculate_Ai(A):
    i_plus_1 = len(A)
    Ai = 0
    for x in range(1, i_plus_1 + 1):
        Px = calculate_Px(x, A)
        if Px is not None:
            Ai += Px
    return Ai

# Case i=4: {a1, a2, a3, a4, a5} = {3, 9, 27, 81, 243}
A4_values = [3, 9, 27, 81, 243]
A4 = calculate_Ai(A4_values)
print(f"A4 for {A4_values}: {A4}")
